// 3D model of the right infratemporal fossa from Z-Anatomy meshes (CC BY-SA
// 4.0, based on BodyParts3D): the ramus, pterygoid plates and temporal bone,
// the muscles of mastication, the temporomandibular joint, the mandibular
// nerve and its branches and the maxillary artery and its branches. The
// auriculotemporal, masseteric, deep temporal and medial pterygoid nerves and
// the otic ganglion are drawn for this app. Geometry and the traced courses
// live in data/infratemporal-meshes.js, generated by tools/export_zanatomy.py.
// Coordinates are centimetres centred on the fossa: +y = superior,
// +z = anterior, the patient's right side is -x.

window.ANATOMY = window.ANATOMY || { regions: {} };
window.ANATOMY.models = window.ANATOMY.models || {};

window.ANATOMY.models.infratemporal = {
  // Default view: the right side, a little from below and in front.
  camera: { target: [0, 0.2, 0.4], radius: 31, theta: -1.25, phi: 1.68 },

  // [theta, phi] for the view buttons. The right side faces -x.
  views: {
    lateral: [-Math.PI / 2, Math.PI / 2],
    inferior: [-0.9, 2.6],
    anterior: [-0.05, 1.6]
  },

  // Starting axial level (0 = bottom of the model, 1 = top): the mandibular notch.
  sectionLevel: 0.36,

  look: {
    mandible: { kind: "bone", opacity: 0.5 },
    maxilla: { kind: "bone" },
    zygomatic: { kind: "bone" },
    sphenoid: { kind: "bone", color: 0xe6d6b4 },
    temporal: { kind: "bone", color: 0xe9dcc0 },
    parietal: { kind: "bone" },
    tmj_capsule: { kind: "cartilage", color: 0xc9c2b0, opacity: 0.6 },
    tmj_disc: { kind: "cartilage", color: 0x9fb7c9 },
    sphenomandibular: { kind: "cartilage", color: 0xd8d0c0 },
    stylomandibular: { kind: "cartilage", color: 0xd8d0c0 },
    pterygospinous: { kind: "cartilage", color: 0xd8d0c0 },
    temporalis: { kind: "muscle", color: 0x9a3c3c },
    masseter: { kind: "muscle", color: 0xa13f3d },
    lpt_superior: { kind: "muscle", color: 0xb5504a },
    lpt_inferior: { kind: "muscle", color: 0xa84640 },
    medial_pterygoid: { kind: "muscle", color: 0x8f3739 },
    superior_constrictor: { kind: "muscle", color: 0xb06058, opacity: 0.7 },
    digastric_post: { kind: "muscle" },
    styloid_muscles: { kind: "muscle", color: 0x9c3a3c },
    parotid: { kind: "gland", color: 0xd9a46e, opacity: 0.55 },
    v3_trunk: { kind: "nerve", color: 0xf2c94c },
    v3_anterior: { kind: "nerve" },
    v3_posterior: { kind: "nerve" },
    ian: { kind: "nerve" },
    lingual_nerve: { kind: "nerve", color: 0xf0d27a },
    buccal_nerve: { kind: "nerve" },
    chorda: { kind: "nerve", color: 0xe8b84a },
    nerve_mylohyoid: { kind: "nerve" },
    v2: { kind: "nerve" },
    facial_nerve: { kind: "nerve" },
    auriculotemporal: { kind: "nerve", color: 0xf0d27a },
    masseteric_nerve: { kind: "nerve" },
    deep_temporal_nerves: { kind: "nerve" },
    nerve_medial_pterygoid: { kind: "nerve" },
    otic_ganglion: { kind: "nerve", color: 0xe8a93a },
    eca: { kind: "artery" },
    maxillary_artery: { kind: "artery" },
    mma: { kind: "artery" },
    accessory_meningeal: { kind: "artery" },
    iaa: { kind: "artery" },
    deep_temporal_arteries: { kind: "artery" },
    buccal_artery: { kind: "artery" },
    psa: { kind: "artery" },
    descending_palatine: { kind: "artery" },
    sphenopalatine: { kind: "artery" },
    pterygoid_canal_artery: { kind: "artery" },
    sta: { kind: "artery" },
    transverse_facial: { kind: "artery" },
    ica: { kind: "artery" },
    maxillary_vein: { kind: "vein" },
    retromandibular: { kind: "vein" },
    ijv: { kind: "vein" },
    s_itf: { kind: "space", color: 0x5fb3ff, opacity: 0.22 }
  },

  build(THREE, h) {
    return h.fromMeshes("infratemporal", this.look);
  }
};
